DO $$ DECLARE d text; BEGIN SELECT pg_get_constraintdef(oid) INTO STRICT d FROM pg_constraint WHERE conrelid='cmd_command'::regclass AND conname='cmd_command_command_type_check'; ALTER TABLE cmd_command DROP CONSTRAINT cmd_command_command_type_check; EXECUTE format('ALTER TABLE cmd_command ADD CONSTRAINT cmd_command_command_type_check %s',replace(d,'CHECK (','CHECK (command_type=''resolve_transport_operation'' OR ')); END $$;
CREATE TABLE cmd_transport_operation_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),actor_id bigint NOT NULL,mechanic_rule_id bigint NOT NULL,skill_rule_id bigint NOT NULL,target_kind text NOT NULL CHECK(target_kind IN('vehicle','ship')),vehicle_id bigint,ship_id bigint,operation_kind text NOT NULL CHECK(operation_kind IN('maneuver','routine-maintenance','operate-spacecraft')),operation_reference text NOT NULL CHECK(btrim(operation_reference)<>''),challenging_conditions boolean NOT NULL,automatic_success boolean NOT NULL,task_command_id bigint UNIQUE REFERENCES cmd_actor_task_receipt(command_id),check_total smallint,effect smallint,succeeded boolean NOT NULL,FOREIGN KEY(actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),FOREIGN KEY(vehicle_id,campaign_id) REFERENCES vehicle_vehicle(vehicle_id,campaign_id),FOREIGN KEY(ship_id,campaign_id) REFERENCES ship_ship(ship_id,campaign_id),FOREIGN KEY(mechanic_rule_id,skill_rule_id) REFERENCES rule_transport_skill_capability(rule_id,skill_rule_id),CHECK((target_kind='vehicle' AND vehicle_id IS NOT NULL AND ship_id IS NULL) OR (target_kind='ship' AND ship_id IS NOT NULL AND vehicle_id IS NULL)),CHECK((automatic_success AND task_command_id IS NULL AND check_total IS NULL AND effect IS NULL AND succeeded) OR (NOT automatic_success AND task_command_id IS NOT NULL AND check_total IS NOT NULL AND effect IS NOT NULL)));
